{
  "method": {
    "cmd": "sqldml",
    "argcnt": 1
  },
  "sqldml": "SELECT category, COUNT(*) as count, AVG(price) as avg_price, MIN(price) as min_price, MAX(price) as max_price FROM products WHERE stock > 0 GROUP BY category HAVING COUNT(*) > 5 ORDER BY avg_price DESC"
}

